import json, subprocess, sys, time, random
def run(req):
    line=json.dumps(req)+'\n'
    t0=time.time()
    r=subprocess.run([sys.executable,'-I','-B','/workspace/submission/main.py'],input=line,capture_output=True,text=True,timeout=200)
    return time.time()-t0, r.stdout.strip()[:40]
def mkflow(rng,fid,nodes,pathlen,H=16,nd=3):
    path=rng.sample(nodes,pathlen)
    kinds=list('K'*H); idx=list(range(H)); rng.shuffle(idx)
    kinds[idx.pop()]='Q'; kinds[idx.pop()]='T'
    for k in rng.sample(idx,nd): kinds[k]='D'
    return dict(id=fid,path=path,template='00'*H,kinds=''.join(kinds))
def gen(seed,nn,pl,cap,mixlen=False):
    rng=random.Random(seed)
    nodes=['n%d'%i for i in range(nn)]
    caps={n:cap for n in nodes}
    flows=[]
    for i in range(22):
        L = rng.randint(2,min(9,nn)) if mixlen else pl
        flows.append(mkflow(rng,'f%02d'%i,nodes,L))
    offers={}
    for f in flows:
        b=bytearray(bytes.fromhex(f['template']))
        b[f['kinds'].index('Q')]=3; b[f['kinds'].index('T')]=250
        offers[f['id']]=[dict(header=bytes(b).hex(),count=1)]
    return dict(mode='plan',capacities=caps,flows=flows,warmup=0,pinned=[],offers=offers)
